<template><section class="api-preview" aria-label="执行详情"><header><h3>执行详情</h3><a-button type="text" size="small" aria-label="关闭执行详情" @click="$emit('close')">×</a-button></header><a-tag :color="record.passed ? 'green' : 'red'">{{ record.passed ? '通过' : record.status === 'error' ? '异常' : '失败' }}</a-tag><h4>{{ record.test_case_name || record.interface_name || record.request_name }}</h4><dl class="api-record-meta"><div v-for="item in meta" :key="item.label"><dt>{{ item.label }}</dt><dd>{{ item.value }}</dd></div></dl><h5>断言结果</h5><ul v-if="record.assertions_results?.length" class="api-record-assertions"><li v-for="(item,index) in record.assertions_results" :key="index"><span :class="item.passed ? 'quality-success' : 'quality-danger'">{{ item.passed ? '✓' : '×' }}</span>{{ item.name || item.type || item.assertion_type || '断言 ' + (index+1) }}<small>{{ item.error || item.message || '' }}</small></li></ul><p v-else>本次执行未记录断言结果。</p><template v-if="record.workflow_steps?.length"><h5>工作流结果</h5><ol><li v-for="(step,index) in record.workflow_steps" :key="index">{{ step.name || '步骤 ' + (index+1) }} · {{ step.passed ? '通过' : '未通过' }}</li></ol></template><div v-if="record.error_message" class="api-error-notice"><strong>错误摘要</strong><p>{{ record.error_message }}</p></div><h5>响应预览</h5><pre>{{ JSON.stringify(record.response_snapshot, null, 2) }}</pre><footer class="api-preview__footer"><a-button type="primary" @click="$emit('logs',record)">查看完整日志与复盘</a-button></footer></section></template>
<script setup lang="ts">
import { computed } from 'vue'
import type { ApiExecutionRecord } from '../types'
const props=defineProps<{record:ApiExecutionRecord}>()
defineEmits<{close:[];logs:[record:ApiExecutionRecord]}>()
const meta=computed(()=>[{label:'执行批次',value:props.record.run_name || props.record.run_id || 'RUN-'+props.record.id},{label:'接口名称',value:props.record.interface_name || props.record.request_name},{label:'执行环境',value:props.record.environment_name || '默认环境'},{label:'执行人',value:props.record.executor_name || '未记录'},{label:'执行耗时',value:props.record.response_time == null ? '—' : props.record.response_time+' ms'},{label:'状态码',value:props.record.status_code ?? '—'},{label:'执行时间',value:new Date(props.record.created_at).toLocaleString('zh-CN')}])
</script>
